def _unity_catalog_estimate(
    connection: Connection, target: ResolvedTarget, checks: list[Check]
) -> MemoryEstimate | None:
    """Sized by the runner's own row and width probes, so a small frame reserves what it
    needs instead of the whole frame cap — two metadata queries, not a data read (#2145).
    """
    from backend.app.datasources.unity_catalog import (
        build_unity_catalog_runner,
        frame_lane_required,
    )

    if target.sampling is None:
        types = [c.expectation_type for c in checks if c.kind == "expectation"]
        if not frame_lane_required(types):
            return None
    if not connection.secret_ref or not target.catalog:
        log.info("run_admission_no_credential", connection_id=str(connection.id))
        return None
    settings = get_settings()
    if target.sampling is not None and 0 < settings.run_max_scan_rows < target.sampling.rows:
        # Refused by the sample cap before any probe or read, so it holds nothing.
        return MemoryEstimate(bytes=0, basis="uc_over_cap")
    try:
        runner = build_unity_catalog_runner(
            config=dict(connection.config),
            secret_ref=connection.secret_ref,
            secret_store=get_secret_store(),
            catalog=target.catalog,
            sampling=target.sampling,
        )
        try:
            rows, row_bytes = runner.probe_frame(table=target.table, schema=target.schema)
        finally:
            runner.close()
    except Exception:
        # A transient failure (a waking warehouse) can clear before the runner's own probes,
        # so reserve the most the runner would load rather than leave it unmetered.
        log.warning(
            "run_admission_uc_probe_failed", connection_id=str(connection.id), exc_info=True
        )
        if settings.run_max_frame_bytes > 0:
            return MemoryEstimate(bytes=settings.run_max_frame_bytes, basis="uc_probe_failed")
        return MemoryEstimate(bytes=0, basis="uc_probe_failed", exclusive=True)
    need = rows * row_bytes
    over_rows = target.sampling is None and 0 < settings.run_max_scan_rows < rows
    if over_rows or 0 < settings.run_max_frame_bytes < need:
        # Refused by the runner's row or frame cap before anything is read.
        return MemoryEstimate(bytes=0, basis="uc_over_cap")
    return MemoryEstimate(
        bytes=need, basis="uc_sample_width" if target.sampling else "uc_frame_width"
    )


def _iceberg_estimate(
    connection: Connection, target: ResolvedTarget, checks: list[Check]
) -> MemoryEstimate | None:
    """The native read materialises the whole current snapshot, so it is sized from the same
    manifest plan the row-cap probe uses, priced per row by Arrow type (#2146).

    Fixed-width columns cost nothing to price. Variable-width ones are sampled from the first
    rows, because rows alone are width-blind and file bytes are blind to dictionary-encoded
    strings, which are small on disk and full-width in memory.
    """
    from backend.app.datasources.iceberg import (
        ICEBERG_RUN_OVERHEAD_BYTES,
        IcebergConfig,
        iceberg_credentials,
        load_iceberg_table,
        planned_row_count,
        snapshot_row_bytes,
        summary_scan_fallback_reason,
    )
    from backend.app.datasources.monitors import (
        FRESHNESS,
        VOLUME,
    )

    kinds = {c.kind for c in checks}
    monitors = kinds & {FRESHNESS, VOLUME}
    if "expectation" not in kinds and not monitors:
        return None
    config = IcebergConfig.model_validate(connection.config)
    secret, catalog_secret = iceberg_credentials(config, connection.secret_ref, get_secret_store())
    table = load_iceberg_table(config, secret, target.table, catalog_secret)
    if "expectation" in kinds:
        basis_prefix = "iceberg"
    else:
        # Monitors answer from snapshot metadata unless it cannot prove the answer; then the
        # volume/freshness fallback scans (a merge-on-read count materialises the tasks).
        reason = summary_scan_fallback_reason(table)
        if reason is None:
            log.info("run_admission_iceberg_metadata_only", connection_id=str(connection.id))
            return None
        log.info(
            "run_admission_iceberg_monitor_fallback",
            connection_id=str(connection.id),
            reason=reason,
        )
        basis_prefix = "iceberg_monitor_fallback"
    rows = planned_row_count(table)
    cap = get_settings().iceberg_scan_row_cap
    if cap > 0 and rows > cap:
        # Refused by the row-cap probe before anything is read, so it holds nothing.
        return MemoryEstimate(bytes=0, basis="iceberg_over_cap")
    if rows == 0:
        # A snapshot-less table reads nothing, so it is not charged the read's overhead.
        return MemoryEstimate(bytes=0, basis=f"{basis_prefix}_empty")
    return MemoryEstimate(
        bytes=ICEBERG_RUN_OVERHEAD_BYTES + rows * snapshot_row_bytes(table),
        basis=f"{basis_prefix}_schema_width",
    )


